function buildHeadwiseRows(c, s, m, headFilter) {
  if (!c || !s || !m) return [];
  const rows = [];
  if ((+s.dues || 0) > 0) {
    rows.push({
      head: 'Custom Account',
      sub: 'Previous Dues',
      total: +s.dues || 0,
      disc: 0,
      recv: Math.min(m.paid, +s.dues),
      pend: Math.max(+s.dues - Math.min(m.paid, +s.dues), 0)
    });
  }
  m.heads.forEach(h => {
    const gen = m.generated;
    const net = h.std - h.disc;
    rows.push({
      head: 'Account Payable',
      sub: h.name,
      total: h.std,
      disc: h.disc,
      recv: gen ? net : 0,
      pend: gen ? 0 : net
    });
  });
  if ((+s.transport || 0) > 0) {
    rows.push({
      head: 'Account Payable',
      sub: 'Transport',
      total: +s.transport,
      disc: 0,
      recv: m.generated ? +s.transport : 0,
      pend: m.generated ? 0 : +s.transport
    });
  }
  if (headFilter && headFilter !== 'All Heads') {
    return rows.filter(r => r.sub === headFilter);
  }
  return rows;
}

