  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 11px 18px;
  border-radius: var(--radius-md);
  border: none;
  background: transparent;
  font-family: var(--font-body);
  font-size: 13px;
  font-weight: 600;
  color: var(--text-muted);
  cursor: pointer;
  transition: var(--tr);
  white-space: nowrap;
  flex: 1;
}
.fee-subtab:hover:not(.active) { background: var(--bg-muted); color: var(--text-primary); }
.fee-subtab.active {
  background: linear-gradient(135deg,#1E3A8A 0%,#1E40AF 60%,#2563EB 100%);
  color: #fff;
  box-shadow: 0 6px 20px rgba(30,58,138,.4), inset 0 1px 0 rgba(255,255,255,.2);
}
.fee-subtab i { font-size: 12px; }

/* Pill segment toggle (used inside Fee Setup & Settings) */
.fee-seg {
  display: flex;
  width: 100%;
  background: var(--bg-card);
  border: 1.5px solid var(--border-light);
  border-radius: var(--radius-full);
  padding: 5px;
  margin-bottom: 18px;
  box-shadow: var(--shadow-sm);
}
.fee-seg-btn {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 10px 16px;
  border: none;
  background: transparent;
  border-radius: var(--radius-full);
  font-family: var(--font-body);
  font-size: 13px;
  font-weight: 700;
  color: var(--text-muted);
  cursor: pointer;
  transition: var(--tr);
  white-space: nowrap;
}
.fee-seg-btn:hover:not(.active) { color: var(--text-primary); }
.fee-seg-btn.active {
  background: linear-gradient(135deg,#1E3A8A,#1E40AF);
  color: #fff;
  box-shadow: 0 4px 12px rgba(30,58,138,.3);
}
.fee-seg-btn i { font-size: 12px; }

@media (max-width: 768px) {
  .fee-seg { flex-wrap: wrap; gap: 6px; border-radius: 14px; overflow: hidden; padding: 6px; }
  .fee-seg-btn {
    flex: 1 1 calc(50% - 6px);
    min-width: 0;
    font-size: 12px;
    padding: 11px 10px;
    border-radius: 10px;
    white-space: normal;
    line-height: 1.2;
    text-align: center;
  }
}

