[data-theme="dark"] .fee-chevbtn:hover,
[data-theme="dark"] .fee-chevbtn.open { background: #3B82F6; color: #fff; }
[data-theme="dark"] .fee-btn-primary { background: linear-gradient(135deg, #1E3A8A, #2563EB); }
